using NUnit.Framework;using UnityEditor;using UnityEditor.AddressableAssets;using UnityEngine;using Rootborn.UI.Modern;namespace Rootborn.Tests.EditMode.UI.Modern{public sealed class UrbanStudentStatusArtTests{[Test]public void StressSymbolUsesReviewedFortyEightPixelSpriteAndSharedTheme(){const string path="Assets/Art/UI/UrbanMolding/urban_icon_stress.png";var s=AssetDatabase.LoadAssetAtPath<Sprite>(path);Assert.That(s,Is.Not.Null);Assert.That(s.rect.size,Is.EqualTo(new Vector2(48,48)));Assert.That(s.pivot,Is.EqualTo(new Vector2(24,24)));Assert.That(s.pixelsPerUnit,Is.EqualTo(16));var i=(TextureImporter)AssetImporter.GetAtPath(path);Assert.That(i.filterMode,Is.EqualTo(FilterMode.Point));Assert.That(i.mipmapEnabled,Is.False);Assert.That(i.textureCompression,Is.EqualTo(TextureImporterCompression.Uncompressed));Assert.That(AddressableAssetSettingsDefaultObject.Settings.FindAssetEntry(AssetDatabase.AssetPathToGUID(path)).address,Is.EqualTo("sprites/ui/urban-life/stress"));var theme=AssetDatabase.LoadAssetAtPath<UrbanUiThemeDefinition>("Assets/Data/UI/UrbanMoldingTheme.asset");Assert.That(theme.GetIcon("stress"),Is.SameAs(s));foreach(string key in new[]{"energy","focus","close"})Assert.That(theme.GetIcon(key),Is.Not.Null);}}}
